import {clone,find,parentOf,reidentify,localName} from './model.js';
import {addTrack,setKeyframe,storyboardTracks,simpleDuration,activeDuration,formatTime,parseTime,clockTime} from './animation.js';
import {ensureTransformPath,readPropertyPath} from './property-path.js';
function localTime(doc,story,track,time){const chain=[];let node=track;while(node){if(/Storyboard|ParallelTimeline|Animation/.test(localName(node.type)))chain.unshift(node);if(node.id===story.id)break;node=parentOf(doc.root,node.id);}for(const n of chain){const repeat=n.props.RepeatBehavior,speed=Number(n.props.SpeedRatio??1);if(n.props.BeginTime==='{x:Null}'||!Number.isFinite(speed)||speed<=0)throw Error('This animation clock is inactive.');if(String(n.props.AutoReverse).toLowerCase()==='true'||repeat&&repeat!=='1x')time=clockTime(n,time);else time=(time-parseTime(n.props.BeginTime,0))*speed;if(time===null||!Number.isFinite(time)||time<0)throw Error('Move the playhead into the active animation interval.');}return time;}
export function recordProperties(doc,storyId,changes,time,{baseDocument=doc}={}){const draft=clone(doc),result=recordDraft(draft,storyId,changes,time,{baseDocument});doc.root=draft.root;return result;}
function recordDraft(doc,storyId,changes,time,{baseDocument=doc}={}){
 const story=find(doc.root,storyId);if(!story)throw Error('Create or select a Storyboard first.');const base=clone(baseDocument);const tracks=[];
 for(const change of changes){const target=find(doc.root,change.id);if(!target)throw Error('Animation target no longer exists.');if(String(change.value).startsWith('{'))throw Error('Record a literal property value.');const track=addTrack(doc,story,target,change.path),property=track.props['Storyboard.TargetProperty'],baseNode=find(base.root,target.id)||clone(target),basePath=ensureTransformPath(base,baseNode,property);const old=storyboardTracks(doc,story).find(t=>t.id===track.id),at=localTime(doc,story,track,time);if(!old.frames.length&&/UsingKeyFrames$/.test(track.type)){const initial=change.baseValue??readPropertyPath(base,baseNode,basePath);setKeyframe(track,0,initial,{interpolation:'Linear'});}setKeyframe(track,at,change.value,{interpolation:'Linear'});if(at>simpleDuration(track))track.props.Duration=formatTime(at);tracks.push(track.id);
 }
 extendClocks(story);return tracks;
}
export function shiftKeyframes(doc,storyId,keyIds,delta,{duplicate=false}={}){
 if(!Number.isFinite(delta))throw Error('Enter a finite time offset.');const story=find(doc.root,storyId);if(!story)throw Error('Storyboard is missing.');const selected=new Set(keyIds),plans=[];
 for(const track of storyboardTracks(doc,story)){const moved=track.frames.filter(f=>selected.has(f.id));if(!moved.length)continue;const destinations=moved.map(f=>Math.round((f.time+delta)*1000)/1000);if(destinations.some(t=>t<0))throw Error('Keyframes cannot move before zero.');if(new Set(destinations).size!==destinations.length)throw Error('Keyframes would overlap.');if(destinations.some(t=>track.frames.some(f=>(duplicate||!selected.has(f.id))&&Math.abs(f.time-t)<.0005)))throw Error('A keyframe already occupies the destination time.');plans.push({track,moved,destinations});}
 if(!plans.length)throw Error('Select one or more keyframes.');const result=[];
 for(const {track,moved,destinations}of plans){moved.forEach((frame,i)=>{const node=duplicate?reidentify(frame.node):frame.node;if(duplicate)parentOf(doc.root,frame.id).children.push(node);node.props.KeyTime=formatTime(destinations[i]);result.push(node.id);});const end=Math.max(...destinations);if(end>simpleDuration(track.node))track.node.props.Duration=formatTime(end);}
 extendClocks(story);return result;
}
export function deleteKeyframes(doc,storyId,keyIds){const allowed=new Set(storyboardTracks(doc,find(doc.root,storyId)).flatMap(t=>t.frames.map(f=>f.id)));for(const id of keyIds)if(allowed.has(id)){const p=parentOf(doc.root,id);p.children=p.children.filter(n=>n.id!==id);}}
export function editKeyframe(doc,storyId,keyId,options){const draft=clone(doc);const result=editDraft(draft,storyId,keyId,options);doc.root=draft.root;return result;}
function editDraft(doc,storyId,keyId,{time,value,interpolation,easing,easingMode,spline}){const story=find(doc.root,storyId),track=storyboardTracks(doc,story).find(t=>t.frames.some(f=>f.id===keyId));if(!track)throw Error('Keyframe no longer exists.');const frame=track.frames.find(f=>f.id===keyId);if(time!==undefined&&time!==frame.time)shiftKeyframes(doc,storyId,[keyId],Number(time)-frame.time);if(value!==undefined||interpolation!==undefined){const current=storyboardTracks(doc,story).find(t=>t.id===track.id).frames.find(f=>f.id===keyId);const old=clone(current.node),easeNode=old.children.flatMap(n=>n.children||[]).find(n=>/Ease$/.test(n.type||''));const edited=setKeyframe(track.node,current.time,value??current.value,{interpolation:interpolation||current.mode,easing:easing||easeNode?.type.replace(/Ease$/,'')||'Cubic',easingMode:easingMode||easeNode?.props.EasingMode||'EaseInOut',spline:spline||old.props.KeySpline||'0.25,0.1,0.25,1'});if(interpolation===undefined&&easing===undefined&&spline===undefined){edited.type=old.type;edited.children=old.children.filter(n=>value===undefined||!n.type?.endsWith('.Value'));for(const [key,v]of Object.entries(old.props))if(!['Value','KeyTime'].includes(key))edited.props[key]=v;}}return keyId;}
export function pasteKeyframes(doc,storyId,clipboard,time){if(!Number.isFinite(time)||clipboard.some(c=>!Number.isFinite(c.time)))throw Error('Enter finite keyframe times.');if(!clipboard.length)return [];const story=find(doc.root,storyId),tracks=storyboardTracks(doc,story),start=Math.min(...clipboard.map(c=>c.time)),plans=clipboard.map(item=>{const track=tracks.find(t=>t.id===item.trackId);if(!track)throw Error('Paste keys into their original Storyboard.');const at=Math.round((time+item.time-start)*1000)/1000;if(at<0||track.frames.some(f=>Math.abs(f.time-at)<.0005))throw Error('A keyframe already occupies the destination.');return {item,track,at};});const keys=new Set();for(const p of plans){const key=p.track.id+':'+p.at;if(keys.has(key))throw Error('Pasted keyframes overlap.');keys.add(key);}const inserted=plans.map(({item,track,at})=>{const key=reidentify(item.node);key.props.KeyTime=formatTime(at);const holder=track.node.children.find(n=>n.type?.endsWith('.KeyFrames'))||track.node;holder.children.push(key);if(at>simpleDuration(track.node))track.node.props.Duration=formatTime(at);if(at>simpleDuration(story))story.props.Duration=formatTime(at);return key.id;});extendClocks(story);return inserted;}

function extendClocks(node){for(const child of node.children||[])extendClocks(child);if(!/^(Storyboard|ParallelTimeline)$/.test(localName(node.type||'')))return;const timed=(node.children||[]).flatMap(n=>n.type?.endsWith('.Children')?n.children:[n]).filter(n=>/Storyboard|ParallelTimeline|Animation/.test(localName(n.type||'')));const required=Math.max(0,...timed.map(child=>parseTime(child.props.BeginTime,0)+activeDuration(child)/Number(child.props.SpeedRatio??1)).filter(Number.isFinite));if(Number.isFinite(required)&&required>simpleDuration(node))node.props.Duration=formatTime(required);}
